use super::*;
use serde_json::{json,Value};
struct Vault(std::path::PathBuf);impl Drop for Vault{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn install(steps:Vec<Value>,schema:Value)->(Vault,String,String){let dir=Vault(crate::vault::testutil::temp_vault("workflow-native-definition"));let digest=crate::actions::schema::workflow_schema_digest(&schema.to_string()).unwrap();let mut actions=steps.iter().filter_map(|s|s["operation"]["definitionDigest"].as_str().map(str::to_owned)).collect::<Vec<_>>();actions.sort();actions.dedup();let definition=json!({"formatVersion":1,"workflowId":"native","entryStepId":steps[0]["stepId"],"inputSchema":schema,"inputSchemaDigest":digest,"steps":steps,"trigger":{"kind":"manual"},"declaredActionDigests":actions,"authoredBy":"human:me"});let store=super::super::files::DefinitionStore::open(&dir.0,"native").unwrap();let draft=store.save_draft(&definition.to_string(),None).unwrap();let published=store.publish(&draft,None).unwrap();(dir,published.definition_hash,digest)}
fn result()->Value{json!({"stepId":"done","label":"Done","operation":{"kind":"result","output":{"kind":"input","path":[]}}})}
#[test]
fn native_definition_projects_only_actual_pinned_file_and_input(){let(vault,version,schema)=install(vec![result()],json!({"type":"object"}));let native=NativeDefinition::load(&vault.0,"native",&version,"{ \"n\": 1 }").unwrap();assert_eq!((native.workflow(),native.version(),native.schema(),native.entry()),("native",version.as_str(),schema.as_str(),"done"));assert_eq!(native.input(),"{\"n\":1}");let steps=native.steps();assert_eq!(steps.len(),1);assert_eq!(steps[0].id,"done");assert!(matches!(steps[0].kind,crate::runtime::workflows::Kind::Result));assert!(steps[0].next.is_none());assert!(native.selectors().is_empty());}
#[test]
fn native_definition_rejects_schema_invalid_input_before_native_rows(){let(vault,version,_)=install(vec![result()],json!({"type":"string"}));assert!(matches!(NativeDefinition::load(&vault.0,"native",&version,"{}"),Err(Error::InvalidInput)));}
#[test]
fn native_definition_never_substitutes_current_version_for_requested_version(){let(vault,version,_)=install(vec![result()],json!({"type":"object"}));assert!(NativeDefinition::load(&vault.0,"native",&version,"{}").is_ok());assert!(matches!(NativeDefinition::load(&vault.0,"native",&"b".repeat(64),"{}"),Err(Error::DefinitionUnavailable)));assert!(matches!(NativeDefinition::load(&vault.0,"other",&version,"{}"),Err(Error::DefinitionUnavailable)));}
#[test]
fn native_definition_projects_each_action_selector_and_sequential_graph(){let selector=crate::actions::workflow_requests::fixture_selectors();let action=|id:&str,next:&str|json!({"stepId":id,"label":id,"operation":{"kind":"action","actionId":selector.action_id,"definitionDigest":selector.definition_digest,"connectionId":selector.connection_id,"accountId":selector.account_id,"input":{"kind":"literal","value":{"repository":"owner/repo","title":"fixture","body":"body"}},"nextStepId":next}});let(vault,version,_)=install(vec![action("one","two"),action("two","done"),result()],json!({"type":"object"}));let native=NativeDefinition::load(&vault.0,"native",&version,"{}").unwrap();let actions=native.selectors();assert_eq!(actions.len(),2);for (actual,step) in actions.iter().zip(["one","two"]){assert_eq!(actual,&ActionSelector{step:step.into(),action:selector.action_id.clone(),definition:selector.definition_digest.clone(),connection:selector.connection_id.clone(),account:selector.account_id.clone()});}let steps=native.steps();assert_eq!(steps.iter().map(|s|(s.id,s.next)).collect::<Vec<_>>(),vec![("one",Some("two")),("two",Some("done")),("done",None)]);}

#[test]
fn native_definition_existing_reader_missing_workflow_never_creates_control_directories(){let vault=Vault(crate::vault::testutil::temp_vault("workflow-missing-read"));assert!(super::super::files::DefinitionStore::read_existing_version(&vault.0,"missing",&"b".repeat(64)).is_err());assert!(!vault.0.join(".cerebro").exists(),"native load must not create missing workflow/control directories");}
#[test]
fn native_definition_existing_reader_does_not_create_a_missing_lock_file(){let(vault,version,_)=install(vec![result()],json!({"type":"object"}));let lock=vault.0.join(".cerebro/workflows/native/.lock");std::fs::remove_file(&lock).unwrap();let loaded=super::super::files::DefinitionStore::read_existing_version(&vault.0,"native",&version).unwrap();assert_eq!(loaded.definition_hash,version);assert!(!lock.exists(),"immutable read needs no writable advisory lock");}
#[test]
fn native_definition_existing_reader_never_repairs_missing_versions_directory(){let(vault,version,_)=install(vec![result()],json!({"type":"object"}));let versions=vault.0.join(".cerebro/workflows/native/versions");std::fs::rename(&versions,vault.0.join("retired-versions")).unwrap();assert!(super::super::files::DefinitionStore::read_existing_version(&vault.0,"native",&version).is_err());assert!(!versions.exists(),"read must not repair/recreate the versions namespace");}
